# -*- coding: utf-8 -*-
"""Ninth hour, noon, and the separately descended common pronoun none."""
import json
from pathlib import Path
from lesson_authoring import entry as E
N=[['拉丁 novem → nōnus','九 → 第九'],['拉丁 nōna hōra','日间计时的第九个小时，按约早六点起算约为下午三点']]
NO=N+[['古英语 nōn → 中古英语 non / noon','第九时、相关祈祷时间；后来转向正午'],['现代英语 noon','正午，通常指钟表上的中午十二点']]
def A(h,a,b):return h+[[a,b]]
W=[
E('noon','/nuːn/','正午；中午十二点','这个词曾经指太阳升起后数到第九个小时，大约是下午三点；后来时间含义提前，才成了今天的正午。','拉丁 nōna hōra“第九时”省略 hōra，传入古英语 nōn，再变成 noon。',NO,'中世纪 noon 的时间含义发生了转移，至十四世纪已有正午义。祈祷、斋戒与用餐时间的变化常被用来解释这种转移，但具体原因并无一个完全确定的答案。现代 at noon 通常指中午十二点；solar noon 则是太阳当天位置最高的时刻，不一定刚好落在当地钟表十二点。','at noon；by noon；around noon；solar noon。','noon 是一个时间点；afternoon 是正午之后的一段时间。不要因“第九”而把现代 noon 译成上午九点。',('The meeting will end at noon.','会议将在中午十二点结束。'),('Please send the revised file by noon tomorrow.','请在明天中午之前发来修改后的文件。'),sources=['https://www.etymonline.com/word/noon']),
E('afternoon','英 /ˌɑːftəˈnuːn/；美 /ˌæftərˈnuːn/','下午','把 noon 当作中午的分界线，after 就把你带到它后面：一天从正午走向傍晚的这一段。','after“在……之后” + noon；中古英语已有对应组合。',A(NO,'中古英语 after + non → afternoon','正午之后 → 下午'),'通常用 in the afternoon；指定某天下午说 on Monday afternoon；this afternoon 前不加 in。afternoon 与 evening 的分界随习惯、季节和语境而变，不必死记成一律六点切换。','this afternoon；in the afternoon；an afternoon walk。','after noon 可临时表示十二点以后；afternoon 是已经固定下来的“下午”这个时间名称。',('I usually take a short walk in the afternoon.','我通常在下午散一小会儿步。'),('We are meeting on Friday afternoon.','我们周五下午见面。'),sources=['https://www.etymonline.com/word/afternoon']),
E('forenoon','英 /ˈfɔːnuːn/；美 /ˈfɔːrnuːn/','午前；上午〔较少用〕','fore- 把视线放在正午以前，因此与 afternoon 在 noon 两边相对。','fore- 在……以前 + noon；英语组合。',A(NO,'英语 fore- + noon → forenoon','正午之前 → 午前、上午'),'日常更常说 morning。forenoon 常见于较旧、正式或航海等特定表达；在 forenoon watch 中，它参与命名值班时段。这里先记午前，不把特定行业时段当作所有语境的定义。','in the forenoon；the forenoon watch；a forenoon session。','fore 是前，four 是四；forenoon 不是“四点之前”。上午用 morning 往往更自然。',('The old diary records a visit in the forenoon.','那本旧日记记着一次上午的拜访。'),('The conference’s forenoon session ended shortly before lunch.','会议的上午场在午饭前不久结束。'),sources=['https://www.merriam-webster.com/dictionary/forenoon']),
E('noonday','/ˈnuːndeɪ/','正午；正午的〔偏书面〕','noon 给出时间，day 把它放进白昼的画面：太阳高、光线强、热气明显的中午。','noon + day；英语复合词。',A(NO,'英语 noon + day → noonday','正午时分 → 正午；正午的'),'常在描写中修饰 sun、heat、light。它与 noon 所指时间重叠，noonday 更容易带出正午的环境画面，并不另指整整一天。','the noonday sun；the noonday heat；at noonday。','midday 是常见的中午表达；noonday 更偏文学或描写，写普通会议时间直接用 noon 即可。',('They rested beneath a tree in the noonday heat.','正午炎热，他们在树下歇息。'),('The white walls shone in the noonday sun.','白墙在正午的阳光下发亮。')),
E('none','常用代词 /nʌn/；教会时辰名词：英 /nəʊn/，美 /noʊn/','没有一个；毫无；第九时祈祷〔另源、罕见名词〕','日常 none 的画面是：检查一群东西，一个也没有符合条件。只有教会时辰那个罕见 none，才属于本页“第九”的词族。','常用代词：古英语 nān = ne“不” + ān“一”；另源时辰名词：拉丁 nōna“第九〔时〕”，经古法语或后期拉丁借入。',[['日耳曼代词支线：古英语 ne + ān → nān → none /nʌn/','不是一个 → 一个也没有'],['另源拉丁支线：nōna hōra → nōna → none /nəʊn, noʊn/','第九时 → 教会时辰及祈祷']],'none of the books 是这些书一本也没有；none of the water 是这些水一点也没有。指可数事物时，谓语单复数可随侧重与语境变化，并非一律只能单数；不可数对象通常接单数。none /nʌn/ 不应硬拆成拉丁 non-“第九”。罕见的时辰名词也拼作 none，常见复数式 nones。','none of；none at all；none of your business。','no 通常直接放在名词前，如 no books；none 可独立或接 of，如 none of these books。not one 强调连一个都没有。',('None of these keys work.','这些钥匙一把也打不开。'),('None of the milk is left.','牛奶一点也没剩。'),('The monastery’s schedule listed the office of none.','修道院的时间表列出了第九时祈祷。'),sources=['https://www.merriam-webster.com/dictionary/none']),
E('nonet','英 /nɒˈnet/；美 /noʊˈnet/','九重奏；九重奏组；九人合奏曲','想象九位演奏者各拿一种乐器，组成一组音乐搭档；同一个词也能指为这九个声部写的作品。','意大利 nonetto，由 nono“第九”构成；nono 接拉丁 nōnus。英语借入音乐名词。',[['拉丁 nōnus → 意大利 nono','第九'],['意大利 nonetto → 英语 nonet','九人合奏、九重奏曲']],'可说 a nonet for wind instruments，也可说 the nonet performed。它的九是演奏人数或声部配置的核心，不是第九乐章，也不一定恰好有九种不同乐器。','a string nonet；a nonet for winds；perform a nonet。','octet 是八重奏，nonet 是九重奏。它们的词尾相似，因为属于同一套音乐命名习惯。',('The composer wrote a nonet for wind instruments.','作曲家写了一首管乐九重奏曲。'),('The nonet performed in a small concert hall.','这个九重奏组在一个小音乐厅演出。'),sources=['https://www.merriam-webster.com/dictionary/nonet','https://www.collinsdictionary.com/dictionary/english/nonet']),
E('nonary','英 /ˈnəʊnəri/；美 /ˈnoʊnəri/','与九有关的；九进制的；第九的〔罕见〕','这里 non- 真与九相连：可以描述九这一数目，数学语境里还可以说逢九进一的记数系统。','拉丁 nōnārius，接 nōnus“第九”；-ary 对应拉丁形容词后缀 -ārius。',[['拉丁 nōnus → nōnārius','第九 → 与九、与第九有关的'],['英语 nonary','九的；九进制的等专门用法']],'九进制用 0 到 8 这九个数字。数到十进制的九时，写作九进制的 10。这个意义由具体数学语境确认；普通“第九”用 ninth 更自然。','a nonary numeral system；nonary notation；a nonary digit。','nonary 不是 non-ary 的否定结构。non- 在另一个词根页常表否定，本词却来自拉丁的九。',('The exercise asks students to write the number in nonary notation.','这道练习要求学生用九进制写出这个数。'),('A nonary numeral system uses nine digits, from 0 to 8.','九进制记数系统使用从 0 到 8 的九个数字。'),sources=['https://dictionary.cambridge.org/us/pronunciation/english/nonary','https://www.dictionary.com/browse/nonary','https://www.collinsdictionary.com/us/dictionary/english/nonary']),
E('nones','英 /nəʊnz/；美 /noʊnz/','古罗马历的诺奈日；第九时祈祷〔历史、宗教〕','古罗马人会从月中某个日期倒着数，算上首尾，第九天叫 Nones；教会又用相近形式命名一天中的第九时。','历法名词接拉丁 nōnae，nōnus 的阴性复数；教会时辰义接 nōna hōra。经法语、拉丁等借词路线进入英语。',[['拉丁 nōnus“第九”：两条用途并列','历法日期；日间第九时'],['历法 nōnae → 英语 nones / Nones','按包含首尾的计日法，在 Ides 之前第九天'],['时辰 nōna hōra → none / nones','第九时及相关祈祷']],'历法的 Nones 是三、五、七、十月的七日，其他月份的五日；不是每月九日，因为它是相对 Ides 倒数的结果。教会的 nones 则指第九时，按传统日间算法约下午三点。两义看语境区分。','the Nones of March；the office of nones；before nones。','现代社会调查还会用 religious nones 指自报没有宗教归属者，那里接的是常用 none /nʌn/，不是这条拉丁“第九”路线。',('In the Roman calendar, the Nones of March fell on the seventh day.','在古罗马历中，三月的诺奈日是三月七日。'),('The monks gathered for nones in the afternoon.','修士们在下午集合，举行第九时祈祷。'),sources=['https://www.ahdictionary.com/word/search.html?q=nones','https://www.etymonline.com/word/noon']),
]
ROOT=dict(id='C0823',meaning='第九；第九时与正午',core='NON = NINTH',image='从日出开始数时辰，第九格原本大约落在下午三点。英语 noon 的时间含义后来向前移到正午，却仍保留那个“第九”的历史外壳。',intro='拉丁 nōnus 表示第九，接 novem“九”。这一族词不多，却能解释一个有趣变化：noon 为什么追到源头会与九有关。另一条音乐支线产生 nonet。常用 none“没有一个”另有日耳曼来源，只有同拼写的教会时辰名词归入本族。',forms='non-、nonary 和 nonet 保留九的线索；noon 的长元音来自它自己的历史演变。noon 与 none /nʌn/ 的拼写相近不能证明同源。否定前缀 non- 也另属一族。',branches=[['正午及前后时段','noon, afternoon, forenoon, noonday'],['音乐与数字九','nonet, nonary'],['旧时辰与古罗马日期','none〔时辰义〕, nones']],contrasts='nones 的古罗马日期不是每月九日；noon 今天不是下午三点；常用 none“没有一个”不是本词根的后代。把历史来源和今天的用法分开，才能既看懂故事又正确使用。',practice='The nonet rehearsed in the forenoon and stopped at noon. None of the musicians stayed for the afternoon session.\n\n九重奏组在上午排练，正午停了下来。没有一位演奏者留下参加下午场。',words=[w['word'] for w in W])
if __name__=='__main__':
 t=Path(__file__).resolve().parents[1]/'.cache/batch200/drafts/root'
 for k,v in [('roots',[ROOT]),('words',W)]: (t/f'{k}_batch200_root_non_ninth.json').write_text(json.dumps(v,ensure_ascii=False,indent=2))
 print(len(W),'individually authored words')
